// Resolve env-aware defaults for the usage report.
const inp = $input.first().json || {};
const env = $vars.env || 'production';
const bot = (inp.bot_user_id && String(inp.bot_user_id).trim()) || (env === 'staging' ? 'U0BLRFB0FJR' : 'U09Q22R53T6');
const otherBot = bot === 'U09Q22R53T6' ? 'U0BLRFB0FJR' : 'U09Q22R53T6';
const oldestStr = (inp.oldest && String(inp.oldest).trim()) || '2026-07-25';
const oldestEpoch = Math.floor(new Date(oldestStr + 'T00:00:00Z').getTime() / 1000);
// Excluded by default: retrieval-eval Slack transport channel and the test-report channel.
const defaults = ['C0BQH5S6P1P', 'C09DRCJLQCE'];
const extra = String(inp.exclude_channels || '').split(',').map(s => s.trim()).filter(Boolean);
return [{ json: { env: env, bot_id: bot, other_bot: otherBot, oldest: String(oldestEpoch), oldest_date: oldestStr, excluded: defaults.concat(extra) } }];

// One item per conversation the bot can read, minus excluded channels.
// users.conversations returns only conversations the bot is a member of.
// Pages from types the token has no scope for come back ok:false and are skipped;
// Build Report re-reads them to report the scope gaps.
const cfg = $('Build Config').first().json;
const out = [];
const gaps = [];
const seen = {};
for (const page of $input.all()) {
  const body = page.json;
  if (!body || body.ok === false) {
    gaps.push((body && (body.needed || body.error)) || 'unknown');
    continue;
  }
  for (const c of (body.channels || [])) {
    if (seen[c.id]) continue;
    seen[c.id] = true;
    if (cfg.excluded.includes(c.id)) continue;
    out.push({ json: { channel_id: c.id, is_im: !!c.is_im, name: c.name || c.user || c.id } });
  }
}
if (!out.length) throw new Error('No readable conversations. Scope gaps: ' + gaps.join(', '));
return out;

// Deduplicate messages and thread-fetch requests across all channels.
const seenMsg = {};
const seenThread = {};
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.kind === 'msg') {
    const k = j.channel_id + ':' + j.ts;
    if (seenMsg[k]) continue;
    seenMsg[k] = true;
    out.push({ json: j });
  } else if (j.kind === 'thread') {
    const k = j.channel_id + ':' + j.thread_ts;
    if (seenThread[k]) continue;
    seenThread[k] = true;
    out.push({ json: j });
  }
}
if (!out.length) out.push({ json: { kind: 'noop' } });
return out;

// Only the thread-fetch requests; a marker item keeps the pipeline alive when there are none.
const out = [];
for (const it of $input.all()) {
  if (it.json.kind === 'thread') out.push({ json: it.json });
}
if (!out.length) out.push({ json: { kind: 'thread', channel_id: '', is_im: false, thread_ts: '' } });
return out;

// Merge direct messages and thread replies, dedupe, aggregate month by month.
const cfg = $('Build Config').first().json;
const all = [];
for (const it of $('Classify Results').all()) {
  if (it.json.kind === 'msg') all.push(it.json);
}
for (const it of $input.all()) {
  if (it.json.kind === 'msg') all.push(it.json);
}
const seen = {};
const msgs = [];
for (const m of all) {
  const k = m.channel_id + ':' + m.ts;
  if (seen[k]) continue;
  seen[k] = true;
  msgs.push(m);
}
const months = {};
const totalUsers = {};
const totalThreads = {};
for (const m of msgs) {
  const month = new Date(parseFloat(m.ts) * 1000).toISOString().slice(0, 7);
  if (!months[month]) months[month] = { users: {}, messages: 0, threads: {} };
  months[month].users[m.user] = (months[month].users[m.user] || 0) + 1;
  months[month].messages += 1;
  months[month].threads[m.channel_id + ':' + m.thread_ts] = true;
  totalUsers[m.user] = (totalUsers[m.user] || 0) + 1;
  totalThreads[m.channel_id + ':' + m.thread_ts] = true;
}
const monthRows = Object.keys(months).sort().map(mo => ({
  month: mo,
  distinct_users: Object.keys(months[mo].users).length,
  messages: months[mo].messages,
  threads: Object.keys(months[mo].threads).length,
  users: Object.entries(months[mo].users).sort((a, b) => b[1] - a[1]).map(e => ({ user: e[0], messages: e[1] }))
}));
// Scope gaps: conversation types the token could not list.
const gaps = [];
for (const it of $('List Conversations').all()) {
  const b = it.json;
  if (b && b.ok === false) gaps.push(b.needed || b.error || 'unknown');
}
return [{ json: {
  env: cfg.env,
  since: cfg.oldest_date,
  excluded_channels: cfg.excluded,
  scope_gaps: gaps,
  months: monthRows,
  totals: { distinct_users: Object.keys(totalUsers).length, messages: msgs.length, threads: Object.keys(totalThreads).length }
} }];

// One item per distinct user for the name lookup.
const rep = $('Build Report').first().json;
const users = {};
for (const mo of rep.months) {
  for (const u of mo.users) users[u.user] = true;
}
const out = Object.keys(users).map(u => ({ json: { user: u } }));
if (!out.length) out.push({ json: { user: 'USLACKBOT' } });
return out;

// Attach display names; fall back to the raw user ID when the lookup fails.
const report = $('Build Report').first().json;
const names = {};
for (const it of $input.all()) {
  const body = it.json;
  if (body && body.ok && body.user) {
    const p = body.user.profile || {};
    names[body.user.id] = p.display_name || p.real_name || body.user.real_name || body.user.name;
  }
}
for (const mo of report.months) {
  for (const u of mo.users) u.name = names[u.user] || u.user;
}
report.generated_at = new Date().toISOString();
return [{ json: report }];

// Qualifying human messages inside one thread.
const t = $('Threads Loop').first().json;
const cfg = $('Build Config').first().json;
const bots = [cfg.bot_id, cfg.other_bot];
const mention = '<@' + cfg.bot_id + '>';
const out = [];
for (const page of $input.all()) {
  const body = page.json;
  if (!body || body.ok === false) continue;
  for (const m of (body.messages || [])) {
    if (m.subtype && m.subtype !== 'thread_broadcast') continue;
    if (!m.user || m.bot_id || bots.includes(m.user)) continue;
    if (!(t.is_im || (m.text || '').includes(mention))) continue;
    out.push({ json: { kind: 'msg', channel_id: t.channel_id, is_im: t.is_im, user: m.user, ts: m.ts, thread_ts: t.thread_ts } });
  }
}
if (!out.length) out.push({ json: { kind: 'noop' } });
return out;

// Keep qualifying human messages and threads that need a replies fetch.
const ch = $('Channels Loop').first().json;
const cfg = $('Build Config').first().json;
const bots = [cfg.bot_id, cfg.other_bot];
const mention = '<@' + cfg.bot_id + '>';
const out = [];
for (const page of $input.all()) {
  const body = page.json;
  if (body.ok === false) continue;
  for (const m of (body.messages || [])) {
    if (m.subtype && m.subtype !== 'thread_broadcast') continue;
    const isHuman = m.user && !m.bot_id && !bots.includes(m.user);
    const qualifies = isHuman && (ch.is_im || (m.text || '').includes(mention));
    const replyUsers = m.reply_users || [];
    const needsReplies = (m.reply_count || 0) > 0 && (replyUsers.some(u => bots.includes(u)) || qualifies || bots.includes(m.user));
    if (qualifies) out.push({ json: { kind: 'msg', channel_id: ch.channel_id, is_im: ch.is_im, user: m.user, ts: m.ts, thread_ts: m.thread_ts || m.ts } });
    if (needsReplies) out.push({ json: { kind: 'thread', channel_id: ch.channel_id, is_im: ch.is_im, thread_ts: m.ts } });
  }
}
// Always emit at least one item so the loop keeps moving.
if (!out.length) out.push({ json: { kind: 'noop' } });
return out;
